// Cofrim — Personagem padrão em imagem (o mascote do app sem tema especial): o Cofrim, um cofrinho-porquinho, numa
// versão para cada uma das 12 cores do app (COLORS, em js/aparencia.js) e para cada humor (feliz, ok e triste).
// Carregado pelo index.html antes de divertido.js. Imagens de 320 x 320 (WebP, fundo transparente, sem sombra: o app
// desenha a sombra e a moeda), geradas em 14/10/2026 (docs/prompt-personagem-padrao.md). Embutidas, vão junto nas
// atualizações das telas (o app.html é um arquivo só) e funcionam sem internet. Os widgets usam as mesmas, em
// android/res/drawable-nodpi/ic_pig_<humor>_<cor>.webp.
const MASCOTE_PADRAO_IMG = {
  indigo:{feliz:'data:image/webp;base64,', ok:'data:image/webp;base64,', triste:'data:image/webp;base64,'},
  esmeralda:{feliz:'data:image/webp;base64,', ok:'data:image/webp;base64,', triste:'data:image/webp;base64,'},
  oceano:{feliz:'data:image/webp;base64,', ok:'data:image/webp;base64,', triste:'data:image/webp;base64,'},
  rosa:{feliz:'data:image/webp;base64,', ok:'data:image/webp;base64,', triste:'data:image/webp;base64,'},
  laranja:{feliz:'data:image/webp;base64,', ok:'data:image/webp;base64,', triste:'data:image/webp;base64,'},
  grafite:{feliz:'data:image/webp;base64,', ok:'data:image/webp;base64,', triste:'data:image/webp;base64,'},
  vermelho:{feliz:'data:image/webp;base64,', ok:'data:image/webp;base64,', triste:'data:image/webp;base64,'},
  roxo:{feliz:'data:image/webp;base64,', ok:'data:image/webp;base64,', triste:'data:image/webp;base64,'},
  turquesa:{feliz:'data:image/webp;base64,', ok:'data:image/webp;base64,', triste:'data:image/webp;base64,'},
  dourado:{feliz:'data:image/webp;base64,', ok:'data:image/webp;base64,', triste:'data:image/webp;base64,'},
  limao:{feliz:'data:image/webp;base64,', ok:'data:image/webp;base64,', triste:'data:image/webp;base64,'},
  cafe:{feliz:'data:image/webp;base64,', ok:'data:image/webp;base64,', triste:'data:image/webp;base64,'}
};
// Imagem do humor pedido na cor dada (padrão: a cor em uso); cor desconhecida usa a padrão (indigo), como o applyTheme.
const mascotePadraoImg = (mood, cor = db.prefs.color) => (MASCOTE_PADRAO_IMG[cor] || MASCOTE_PADRAO_IMG.indigo)[mood === 'feliz' || mood === 'triste' ? mood : 'ok'];
